import { useState, useEffect, useRef } from "react";

// =============================================
// STYLES (all CSS in JS for single-file setup)
// =============================================
const styles = {
  app: {
    display: "flex",
    height: "100vh",
    background: "#fff5f7",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
  },

  // --- Sidebar ---
  sidebar: {
    width: "220px",
    background: "#fff",
    borderRight: "1px solid #fce4ec",
    display: "flex",
    flexDirection: "column",
    padding: "24px 0",
    boxShadow: "2px 0 12px rgba(233,30,99,0.05)",
    flexShrink: 0,
  },
  logo: {
    padding: "0 24px 28px",
    fontSize: "20px",
    fontWeight: "700",
    color: "#e91e63",
    letterSpacing: "-0.5px",
  },
  logoSub: { fontSize: "11px", color: "#f48fb1", fontWeight: "400", display: "block" },
  navItem: (active) => ({
    display: "flex",
    alignItems: "center",
    gap: "12px",
    padding: "12px 24px",
    cursor: "pointer",
    fontSize: "14px",
    fontWeight: active ? "600" : "400",
    color: active ? "#e91e63" : "#555",
    background: active ? "#fce4ec" : "transparent",
    borderLeft: active ? "3px solid #e91e63" : "3px solid transparent",
    transition: "all 0.2s",
  }),
  navIcon: { fontSize: "16px", width: "20px", textAlign: "center" },

  // --- Main content ---
  main: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    overflow: "hidden",
  },
  header: {
    background: "#fff",
    borderBottom: "1px solid #fce4ec",
    padding: "18px 32px",
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
  },
  headerTitle: { fontSize: "18px", fontWeight: "600", color: "#222" },
  headerBadge: {
    background: "#fce4ec",
    color: "#e91e63",
    fontSize: "12px",
    padding: "4px 12px",
    borderRadius: "20px",
    fontWeight: "500",
  },
  content: {
    flex: 1,
    padding: "28px 32px",
    overflowY: "auto",
  },

  // --- Cards ---
  card: {
    background: "#fff",
    borderRadius: "14px",
    padding: "20px 24px",
    boxShadow: "0 2px 12px rgba(233,30,99,0.06)",
    border: "1px solid #fce4ec",
    marginBottom: "16px",
  },

  // --- Dashboard stat cards ---
  statsGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(3, 1fr)",
    gap: "16px",
    marginBottom: "24px",
  },
  statCard: (color) => ({
    background: "#fff",
    borderRadius: "14px",
    padding: "24px",
    textAlign: "center",
    boxShadow: "0 2px 12px rgba(0,0,0,0.05)",
    border: `1px solid ${color}22`,
  }),
  statNumber: (color) => ({
    fontSize: "40px",
    fontWeight: "700",
    color: color,
    lineHeight: 1,
  }),
  statLabel: {
    fontSize: "13px",
    color: "#888",
    marginTop: "6px",
  },

  // --- Chat ---
  chatContainer: {
    display: "flex",
    flexDirection: "column",
    height: "calc(100vh - 140px)",
  },
  chatHeader: {
    background: "#fff",
    border: "1px solid #fce4ec",
    borderRadius: "14px 14px 0 0",
    padding: "16px 20px",
    display: "flex",
    alignItems: "center",
    gap: "12px",
  },
  chatMessages: {
    flex: 1,
    overflowY: "auto",
    padding: "20px",
    background: "#fff",
    border: "1px solid #fce4ec",
    borderTop: "none",
    display: "flex",
    flexDirection: "column",
    gap: "12px",
  },
  bubble: (isSender) => ({
    maxWidth: "65%",
    padding: "10px 16px",
    borderRadius: isSender ? "18px 18px 4px 18px" : "18px 18px 18px 4px",
    background: isSender ? "#e91e63" : "#f5f5f5",
    color: isSender ? "#fff" : "#333",
    alignSelf: isSender ? "flex-end" : "flex-start",
    fontSize: "14px",
    lineHeight: "1.5",
  }),
  bubbleTime: (isSender) => ({
    fontSize: "10px",
    color: isSender ? "#f8bbd0" : "#aaa",
    marginTop: "4px",
    textAlign: isSender ? "right" : "left",
  }),
  chatInputArea: {
    display: "flex",
    gap: "10px",
    padding: "14px",
    background: "#fff",
    border: "1px solid #fce4ec",
    borderTop: "none",
    borderRadius: "0 0 14px 14px",
  },
  input: {
    flex: 1,
    padding: "10px 16px",
    borderRadius: "24px",
    border: "1px solid #fce4ec",
    fontSize: "14px",
    outline: "none",
    background: "#fff5f7",
  },
  sendBtn: {
    background: "#e91e63",
    color: "#fff",
    border: "none",
    borderRadius: "24px",
    padding: "10px 22px",
    cursor: "pointer",
    fontSize: "14px",
    fontWeight: "600",
    transition: "opacity 0.2s",
  },

  // --- Feedback ---
  feedbackCard: {
    background: "#fff",
    borderRadius: "12px",
    padding: "18px 20px",
    border: "1px solid #fce4ec",
    marginBottom: "12px",
    boxShadow: "0 1px 6px rgba(233,30,99,0.05)",
  },
  anonBadge: {
    display: "inline-block",
    background: "#fce4ec",
    color: "#e91e63",
    fontSize: "11px",
    padding: "2px 10px",
    borderRadius: "20px",
    marginBottom: "8px",
    fontWeight: "500",
  },

  // --- Alerts ---
  alertCard: (severity) => ({
    background: "#fff",
    borderRadius: "12px",
    padding: "18px 20px",
    border: `1px solid ${severity === "HIGH" ? "#ffcdd2" : severity === "MEDIUM" ? "#fff9c4" : "#c8e6c9"}`,
    marginBottom: "12px",
    boxShadow: "0 1px 6px rgba(0,0,0,0.04)",
  }),
  severityBadge: (severity) => ({
    display: "inline-block",
    fontSize: "11px",
    fontWeight: "600",
    padding: "2px 10px",
    borderRadius: "20px",
    background: severity === "HIGH" ? "#ffebee" : severity === "MEDIUM" ? "#fffde7" : "#e8f5e9",
    color: severity === "HIGH" ? "#c62828" : severity === "MEDIUM" ? "#f57f17" : "#2e7d32",
    marginLeft: "8px",
  }),
};

// =============================================
// API HELPER FUNCTIONS
// =============================================
const API = "http://localhost:8080/api";

async function apiGet(path) {
  const res = await fetch(API + path);
  return res.json();
}

async function apiPost(path, body) {
  const res = await fetch(API + path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  return res.json();
}

// Format timestamp nicely
function formatTime(ts) {
  if (!ts) return "";
  const d = new Date(ts);
  return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

// =============================================
// SIDEBAR COMPONENT
// =============================================
function Sidebar({ active, setActive }) {
  const tabs = [
    { id: "dashboard", label: "Dashboard", icon: "⊞" },
    { id: "chat", label: "Private Chat", icon: "💬" },
    { id: "feedback", label: "Express / Feedback", icon: "📢" },
    { id: "alerts", label: "Security Alerts", icon: "🔔" },
  ];

  return (
    <div style={styles.sidebar}>
      <div style={styles.logo}>
        PrivyNet
        <span style={styles.logoSub}>Secure Enterprise Comm</span>
      </div>

      {tabs.map((tab) => (
        <div
          key={tab.id}
          style={styles.navItem(active === tab.id)}
          onClick={() => setActive(tab.id)}
        >
          <span style={styles.navIcon}>{tab.icon}</span>
          {tab.label}
        </div>
      ))}

      {/* User indicator at bottom */}
      <div style={{ marginTop: "auto", padding: "0 24px 8px" }}>
        <div style={{ fontSize: "12px", color: "#bbb", marginBottom: "6px" }}>Logged in as</div>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: "8px",
            background: "#fce4ec",
            borderRadius: "10px",
            padding: "8px 12px",
          }}
        >
          <div
            style={{
              width: "28px", height: "28px",
              background: "#e91e63",
              borderRadius: "50%",
              display: "flex", alignItems: "center", justifyContent: "center",
              color: "#fff", fontSize: "13px", fontWeight: "600",
            }}
          >
            A
          </div>
          <div>
            <div style={{ fontSize: "13px", fontWeight: "600", color: "#333" }}>Alice</div>
            <div style={{ fontSize: "11px", color: "#e91e63" }}>● Online</div>
          </div>
        </div>
      </div>
    </div>
  );
}

// =============================================
// DASHBOARD TAB
// =============================================
function Dashboard() {
  const [counts, setCounts] = useState({ messages: 0, feedback: 0, alerts: 0 });

  useEffect(() => {
    // Fetch summary counts only — NOT the actual content
    Promise.all([
      apiGet("/messages/count"),
      apiGet("/feedback/count"),
      apiGet("/alerts/count"),
    ]).then(([m, f, a]) => {
      setCounts({
        messages: m.count || 0,
        feedback: f.count || 0,
        alerts:   a.count || 0,
      });
    }).catch(() => console.log("Backend not connected yet"));
  }, []);

  return (
    <div>
      <p style={{ color: "#888", fontSize: "14px", marginBottom: "24px" }}>
        Welcome back, Alice. Here's your activity overview.
      </p>

      {/* Summary stats — numbers only, no message content */}
      <div style={styles.statsGrid}>
        <div style={styles.statCard("#e91e63")}>
          <div style={styles.statNumber("#e91e63")}>{counts.messages}</div>
          <div style={styles.statLabel}>Private Messages</div>
        </div>
        <div style={styles.statCard("#9c27b0")}>
          <div style={styles.statNumber("#9c27b0")}>{counts.feedback}</div>
          <div style={styles.statLabel}>Feedback Posts</div>
        </div>
        <div style={styles.statCard("#f44336")}>
          <div style={styles.statNumber("#f44336")}>{counts.alerts}</div>
          <div style={styles.statLabel}>Security Alerts</div>
        </div>
      </div>

      {/* Info cards */}
      <div style={styles.card}>
        <h3 style={{ fontSize: "15px", fontWeight: "600", marginBottom: "8px", color: "#333" }}>
          🔒 Security Status
        </h3>
        <p style={{ fontSize: "14px", color: "#666", lineHeight: "1.6" }}>
          All messages are encrypted with AES-128. RSA key exchange is active.
          Your communications are secure.
        </p>
      </div>

      <div style={styles.card}>
        <h3 style={{ fontSize: "15px", fontWeight: "600", marginBottom: "8px", color: "#333" }}>
          📋 Quick Guide
        </h3>
        <ul style={{ fontSize: "14px", color: "#666", lineHeight: "2", paddingLeft: "18px" }}>
          <li><strong>Private Chat</strong> — encrypted one-to-one messaging</li>
          <li><strong>Express / Feedback</strong> — submit anonymous feedback</li>
          <li><strong>Security Alerts</strong> — view flagged activity</li>
        </ul>
      </div>
    </div>
  );
}

// =============================================
// PRIVATE CHAT TAB
// =============================================
function PrivateChat() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [chatWith, setChatWith] = useState("Bob");  // who you're chatting with
  const [myName] = useState("Alice");               // logged-in user
  const messagesEndRef = useRef(null);

  const users = ["Bob", "Carol", "David", "Eve"];   // other users to chat with

  // Load messages when component mounts or chatWith changes
  useEffect(() => {
    loadMessages();
    const interval = setInterval(loadMessages, 3000); // poll every 3 seconds
    return () => clearInterval(interval);
  }, [chatWith]);

  // Scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  async function loadMessages() {
    try {
      const data = await apiGet(`/messages?user1=${myName}&user2=${chatWith}`);
      setMessages(data);
    } catch {
      // Backend not running — show placeholder
      setMessages([
        { id: 1, sender: "Bob", receiver: "Alice", content: "Hey Alice! Start the Spring Boot server to see real messages.", timestamp: new Date().toISOString() },
      ]);
    }
  }

  async function sendMessage() {
    if (!input.trim()) return;
    try {
      await apiPost("/messages/send", {
        sender: myName,
        receiver: chatWith,
        content: input.trim(),
      });
      setInput("");
      loadMessages();
    } catch {
      alert("Backend not running. Start the Spring Boot server first.");
    }
  }

  function handleKey(e) {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  }

  return (
    <div style={styles.chatContainer}>
      {/* Chat header with user selector */}
      <div style={styles.chatHeader}>
        <div
          style={{
            width: "36px", height: "36px",
            background: "#e91e63",
            borderRadius: "50%",
            display: "flex", alignItems: "center", justifyContent: "center",
            color: "#fff", fontWeight: "700", fontSize: "15px",
          }}
        >
          {chatWith[0]}
        </div>
        <div>
          <div style={{ fontWeight: "600", fontSize: "15px", color: "#222" }}>
            Chat with {chatWith}
          </div>
          <div style={{ fontSize: "12px", color: "#4caf50" }}>● Secure & Encrypted</div>
        </div>

        {/* User switcher */}
        <div style={{ marginLeft: "auto", display: "flex", gap: "8px" }}>
          {users.map((u) => (
            <button
              key={u}
              onClick={() => setChatWith(u)}
              style={{
                padding: "6px 14px",
                borderRadius: "20px",
                border: "1px solid #fce4ec",
                background: chatWith === u ? "#e91e63" : "#fff",
                color: chatWith === u ? "#fff" : "#888",
                cursor: "pointer",
                fontSize: "12px",
                fontWeight: "500",
              }}
            >
              {u}
            </button>
          ))}
        </div>
      </div>

      {/* Message bubbles */}
      <div style={styles.chatMessages}>
        {messages.length === 0 && (
          <div style={{ textAlign: "center", color: "#ccc", marginTop: "60px", fontSize: "14px" }}>
            No messages yet. Say hello! 👋
          </div>
        )}
        {messages.map((msg) => {
          const isSender = msg.sender === myName;
          return (
            <div key={msg.id} style={{ alignSelf: isSender ? "flex-end" : "flex-start" }}>
              {!isSender && (
                <div style={{ fontSize: "11px", color: "#aaa", marginBottom: "2px", paddingLeft: "4px" }}>
                  {msg.sender}
                </div>
              )}
              <div style={styles.bubble(isSender)}>{msg.content}</div>
              <div style={styles.bubbleTime(isSender)}>{formatTime(msg.timestamp)}</div>
            </div>
          );
        })}
        <div ref={messagesEndRef} />
      </div>

      {/* Input area */}
      <div style={styles.chatInputArea}>
        <input
          style={styles.input}
          type="text"
          placeholder={`Message ${chatWith}... (AES encrypted)`}
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKey}
        />
        <button style={styles.sendBtn} onClick={sendMessage}>
          Send 🔐
        </button>
      </div>
    </div>
  );
}

// =============================================
// EXPRESS / FEEDBACK TAB
// =============================================
function FeedbackTab() {
  const [feedbacks, setFeedbacks] = useState([]);
  const [input, setInput] = useState("");
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    loadFeedback();
  }, []);

  async function loadFeedback() {
    try {
      const data = await apiGet("/feedback");
      setFeedbacks(data);
    } catch {
      setFeedbacks([
        { id: 1, content: "Start the Spring Boot backend to see real feedback.", timestamp: new Date().toISOString() },
      ]);
    }
  }

  async function submitFeedback() {
    if (!input.trim()) return;
    setSubmitting(true);
    try {
      await apiPost("/feedback/submit", { content: input.trim() });
      setInput("");
      await loadFeedback(); // refresh list
    } catch {
      alert("Backend not running. Start the Spring Boot server first.");
    }
    setSubmitting(false);
  }

  return (
    <div>
      {/* Submit form */}
      <div style={{ ...styles.card, marginBottom: "24px" }}>
        <h3 style={{ fontSize: "15px", fontWeight: "600", marginBottom: "4px", color: "#333" }}>
          📢 Submit Anonymous Feedback
        </h3>
        <p style={{ fontSize: "13px", color: "#aaa", marginBottom: "14px" }}>
          Your identity will never be recorded or stored.
        </p>
        <textarea
          style={{
            width: "100%",
            padding: "12px 16px",
            borderRadius: "10px",
            border: "1px solid #fce4ec",
            fontSize: "14px",
            outline: "none",
            resize: "vertical",
            minHeight: "90px",
            background: "#fff5f7",
            fontFamily: "inherit",
          }}
          placeholder="Share your thoughts anonymously..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
        />
        <button
          style={{ ...styles.sendBtn, marginTop: "12px", opacity: submitting ? 0.6 : 1 }}
          onClick={submitFeedback}
          disabled={submitting}
        >
          {submitting ? "Submitting..." : "Submit Anonymously"}
        </button>
      </div>

      {/* Feedback list */}
      <h3 style={{ fontSize: "15px", fontWeight: "600", color: "#444", marginBottom: "14px" }}>
        All Feedback ({feedbacks.length})
      </h3>

      {feedbacks.length === 0 && (
        <div style={{ textAlign: "center", color: "#ccc", padding: "40px", fontSize: "14px" }}>
          No feedback yet. Be the first to share!
        </div>
      )}

      {[...feedbacks].reverse().map((fb) => (
        <div key={fb.id} style={styles.feedbackCard}>
          <span style={styles.anonBadge}>Anonymous</span>
          <p style={{ fontSize: "14px", color: "#333", lineHeight: "1.6" }}>{fb.content}</p>
          <p style={{ fontSize: "11px", color: "#bbb", marginTop: "8px" }}>
            {fb.timestamp ? new Date(fb.timestamp).toLocaleString() : "Just now"}
          </p>
        </div>
      ))}
    </div>
  );
}

// =============================================
// SECURITY ALERTS TAB
// =============================================
function SecurityAlerts() {
  const [alerts, setAlerts] = useState([]);

  useEffect(() => {
    apiGet("/alerts").then(setAlerts).catch(() => {
      setAlerts([
        { id: 1, type: "SUSPICIOUS_LOGIN", description: "Start backend to see real alerts.", severity: "HIGH", timestamp: new Date().toISOString() },
      ]);
    });
  }, []);

  const icons = {
    HIGH: "🔴",
    MEDIUM: "🟡",
    LOW: "🟢",
  };

  return (
    <div>
      <p style={{ fontSize: "14px", color: "#888", marginBottom: "24px" }}>
        Showing {alerts.length} security event{alerts.length !== 1 ? "s" : ""} detected by PrivyNet.
      </p>

      {alerts.map((alert) => (
        <div key={alert.id} style={styles.alertCard(alert.severity)}>
          <div style={{ display: "flex", alignItems: "center", marginBottom: "8px" }}>
            <span style={{ fontSize: "16px" }}>{icons[alert.severity] || "⚪"}</span>
            <strong style={{ fontSize: "14px", color: "#333", marginLeft: "8px" }}>
              {alert.type?.replace(/_/g, " ")}
            </strong>
            <span style={styles.severityBadge(alert.severity)}>{alert.severity}</span>
          </div>
          <p style={{ fontSize: "14px", color: "#555", lineHeight: "1.6" }}>
            {alert.description}
          </p>
          <p style={{ fontSize: "11px", color: "#bbb", marginTop: "8px" }}>
            {alert.timestamp ? new Date(alert.timestamp).toLocaleString() : ""}
          </p>
        </div>
      ))}
    </div>
  );
}

// =============================================
// MAIN APP COMPONENT
// =============================================
const tabHeaders = {
  dashboard: { title: "Dashboard", badge: "Overview" },
  chat:      { title: "Private Chat", badge: "AES Encrypted" },
  feedback:  { title: "Express / Feedback", badge: "Anonymous" },
  alerts:    { title: "Security Alerts", badge: "Monitoring" },
};

export default function App() {
  const [activeTab, setActiveTab] = useState("dashboard");

  const header = tabHeaders[activeTab];

  return (
    <div style={styles.app}>
      {/* Fixed sidebar */}
      <Sidebar active={activeTab} setActive={setActiveTab} />

      {/* Main area */}
      <div style={styles.main}>
        <div style={styles.header}>
          <span style={styles.headerTitle}>{header.title}</span>
          <span style={styles.headerBadge}>{header.badge}</span>
        </div>

        <div style={styles.content}>
          {/* Only the matching component renders — no cross-tab data */}
          {activeTab === "dashboard" && <Dashboard />}
          {activeTab === "chat"      && <PrivateChat />}
          {activeTab === "feedback"  && <FeedbackTab />}
          {activeTab === "alerts"    && <SecurityAlerts />}
        </div>
      </div>
    </div>
  );
}
